interface.signature:
POST /api/v1/auth/register
Request: { email: string, password: string, fullName: string }
Response: { data: { id: number, email: string, fullName: string, role: string } }
Error: 409 Conflict for duplicate email, 400 Bad Request for validation errors

POST /api/v1/auth/login
Request: { email: string, password: string, rememberMe?: boolean }
Response: { data: { accessToken: string } }
Cookie: refreshToken (HttpOnly, Secure, SameSite=Strict)
Error: 401 Unauthorized for invalid credentials, 423 Locked for account lockout

POST /api/v1/auth/forgot-password
Request: { email: string }
Response: { data: { message: string } }
Error: 404 Not Found if email not found (security: don't reveal existence)

POST /api/v1/auth/reset-password
Request: { token: string, password: string }
Response: { data: { message: string } }
Error: 400 Bad Request for invalid/expired token, validation errors

public interface AuthService {
  AuthResponse login(LoginRequest request, HttpServletRequest httpRequest);
  AuthResponse refresh(String refreshToken);
  void logout(String refreshToken);
  User register(RegisterRequest request);
  void requestPasswordReset(String email);
  void resetPassword(String token, String newPassword);
}
